import{_ as e,o as a,c as r,aj as o}from"./chunks/framework.BwH0p-pt.js";const h=JSON.parse('{"title":"Product Types","description":"","frontmatter":{},"headers":[],"relativePath":"3.0/products/index.md","filePath":"3.0/products/index.md","lastUpdated":1785836850000}'),i={name:"3.0/products/index.md"};function n(s,t,l,c,d,u){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="product-types" tabindex="-1">Product Types <a class="header-anchor" href="#product-types" aria-label="Permalink to &quot;Product Types&quot;">​</a></h1><h2 id="simple-product" tabindex="-1">Simple Product <a class="header-anchor" href="#simple-product" aria-label="Permalink to &quot;Simple Product&quot;">​</a></h2><p>A simple product is the most basic and common product type. It&#39;s a physical, unique, standalone product without any other variations.</p><p>Simple products offer customizable options within a single SKU.</p><p>See <strong><a href="./simple.html">Simple Product</a></strong> for the full guide.</p><h2 id="configurable-product" tabindex="-1">Configurable Product <a class="header-anchor" href="#configurable-product" aria-label="Permalink to &quot;Configurable Product&quot;">​</a></h2><p>It refers to a type of product that offers various options or variations, such as size, color, or features, which can be selected by the customer.</p><p>In UnoPim 3.0, these options are defined by a <strong>variant structure</strong> on the attribute family — with up to <strong>two variant levels</strong> (e.g., style → colour → size). Shared information is enriched once on the parent and inherited by every variant automatically, so your team only maintains what actually differs.</p><p>See <strong><a href="./configurable.html">Configurable Product</a></strong> for the step-by-step guide, and <strong><a href="./variants.html">Product Variants</a></strong> for the variant model — levels, axes, variant groups, and inheritance.</p><h2 id="new-in-v3-0" tabindex="-1">New in v3.0 <a class="header-anchor" href="#new-in-v3-0" aria-label="Permalink to &quot;New in v3.0&quot;">​</a></h2><ul><li><strong><a href="./variants.html">Product Variants</a></strong> — two-level variant structures with configurable axes per attribute family, inherited values, and variant groups. Enrich shared data once on the parent; child products inherit it automatically.</li><li><strong><a href="./filters-and-views.html">Filters &amp; Saved Views</a></strong> — filter the product grid by category, completeness, dates, properties, and attribute values with type-specific operators, then save filter + column combinations as reusable views. Mass actions can target all matching products across pages and run in the background for large selections.</li></ul>',11)])])}const f=e(i,[["render",n]]);export{h as __pageData,f as default};
